update public.questions set marks = 4, stem = 'ག༽ འོག་གི་མིང་ཚིག་ཚུ་གི་ རྣམ་གྲངས་ ཡིག་རྒྱུགས་ནང་ལས་འཚོལ་ཏེ་བྲིས། (སྐུགས་ ༦x༠.༥=༣)
༡) ལེགས་ཤོམ་བཟོ།  ༢) གོ་ལ།  ༣) ཧ་ལས་སི་སི།  ༤) འབད་གཞག་བཅའ་གཞག།  ༥) དགོ་འདོད་ཆེ།  ༦) རྨགཔ་དང་ཨམ་སྲུ།

(Marks: 4 - set to the latest RCSC layout; the 2021 paper gave 3.)', key_points = '[{"point": "ལེགས་ཤོམ་བཟོ → བཅོས་ཁ་རྐྱབ། གོ་ལ → གྱོན་ཆས། ཧ་ལས་སི་སི → ཡ་མཚན་ཆེ། འབད་གཞག་བཅའ་གཞག → བྱ་བ་སྤྱོད་ལམ། དགོ་འདོད་ཆེ → འདོདཔ་ཆེ། རྨགཔ་དང་ཨམ་སྲུ → ཁྱིམ་ཚང་ / གཉེན་གྲོགས (to confirm) (ཚིག་རེ་ལུ་ ༠.༥)", "marks": 4.0}]'::jsonb where ai_review->>'batch' = 'ME Paper I (Technical): BCSE 2021, batch 5' and passage_group = 'me-technical-1-2021b5-dz' and passage_position = 3;
