insert into public.rubric_criteria (question_id, label, description, max_marks, position) select (select id from public.questions where ai_review->>'batch' = 'ME Paper I (Technical): BCSE 2024, batch 2' and passage_group = 'me-technical-1-2024b2-dz' and passage_position = 1), v.l, v.d, v.m, v.p from (values ('Content and relevance', 'Answers exactly what is asked with correct, relevant points (and evidence from the passage where asked).', 5.5, 1), ('Analysis and examples', 'Explains reasons and effects, gives Bhutanese examples and practical suggestions.', 3.0, 2), ('Language', 'Correct grammar, spelling and vocabulary (Dzongkha items: spelling and honorifics).', 2.5, 3), ('Organisation', 'Logical order, paragraphs or points.', 2.0, 4)) as v(l, d, m, p);
