select p.code, q.ai_review->'source'->>'year' yr, q.question_type, sum(q.marks) from public.questions q join public.exam_papers p on p.id = q.paper_id where p.code = 'me-technical-1' and q.question_type in ('passage','translation') and q.origin='historical_official' group by 1,2,3 order by 2,3;
